 public static object Main(){if(Application.isPlaying||Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets")throw new Exception("Correct EditMode required");var c=UnityEngine.Object.FindAnyObjectByType<GameClient>(FindObjectsInactive.Include);var b=c.GetComponent<PenguinModePaletteBindings>();var root=c.MineMode.mineStart_ui.transform.Find("MinePack/MinePack_Panel/Panel");var list=b.Graphics.ToList();void Set(Graphic g,PenguinModePaletteBindings.Role role){list.RemoveAll(x=>x.Graphic==g);list.Add(new PenguinModePaletteBindings.Binding{Graphic=g,ColorRole=role,Alpha=1});g.color=b.Palette.Get(role);EditorUtility.SetDirty(g);if(PrefabUtility.IsPartOfPrefabInstance(g))PrefabUtility.RecordPrefabInstancePropertyModifications(g);}Set(root.Find("Dia").GetComponent<Image>(),PenguinModePaletteBindings.Role.Button);foreach(var t in new[]{root.Find("Dia/Price_txt").GetComponent<TMP_Text>(),root.Find("I2_txt(Outline)").GetComponent<TMP_Text>()}){Set(t,PenguinModePaletteBindings.Role.OnButton);var guid=AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(t.font));t.fontSharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Game/PenguinModeUIV3/OnBlue-"+guid+".mat");var style=t.GetComponent<WeaponTextStyle>();if(style!=null&&style.Authored){var so=new SerializedObject(style);so.FindProperty("authoredMaterial").objectReferenceValue=t.fontSharedMaterial;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(style);}EditorUtility.SetDirty(t);}b.Graphics=list.ToArray();EditorUtility.SetDirty(b);if(PrefabUtility.IsPartOfPrefabInstance(b))PrefabUtility.RecordPrefabInstancePropertyModifications(b);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(c.gameObject.scene);bool saved=EditorSceneManager.SaveScene(c.gameObject.scene);return new{saved,adjusted=3};}
